1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.dominio.clube.NivelClube;
4	import com.loja.checkout.dominio.cupom.Cupom;
5	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
6	import com.loja.checkout.dominio.pagamento.FormaPagamento;
7	import com.loja.checkout.dominio.pagamento.ResultadoPagamento;
8	import com.loja.checkout.dominio.regiao.Regiao;
9	import com.loja.checkout.web.CheckoutRequest;
10	import com.loja.checkout.web.CheckoutResponse;
11	import org.springframework.stereotype.Component;
12	
13	import java.math.BigDecimal;
14	import java.util.ArrayList;
15	import java.util.List;
16	
17	@Component
18	public class CalculadoraResumo {
19	
20	    public CheckoutResponse calcular(CheckoutRequest req) {
21	        List<Item> itens = validaItens(req.itens());
22	        NivelClube nivel = parse(NivelClube.class, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
23	        Regiao regiao = parse(Regiao.class, req.regiao(), "REGIAO_INVALIDA");
24	        ModalidadeEntrega modal = parse(ModalidadeEntrega.class, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
25	
26	        BigDecimal subtotal = Dinheiro.aCentavos(somaProdutos(itens));
27	        BigDecimal peso = somaPeso(itens);
28	
29	        if (!modal.disponivelPara(peso)) throw new ErroPedido("MODALIDADE_INDISPONIVEL");
30	
31	        Cupom cupom = null;
32	        if (req.cupom() != null && !req.cupom().isBlank()) {
33	            cupom = parse(Cupom.class, req.cupom(), "CUPOM_INVALIDO");
34	            if (!cupom.aplicavel(subtotal)) throw new ErroPedido("CUPOM_NAO_APLICAVEL");
35	        }
36	
37	        FormaPagamento forma = parse(FormaPagamento.class, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
38	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
39	        if (!forma.parcelasValidas(parcelas)) throw new ErroPedido("PARCELAMENTO_INVALIDO");
40	
41	        BigDecimal freteBruto = modal.custoBruto(peso);
42	        BigDecimal frete = Dinheiro.aCentavos(nivel.ajustaFrete(freteBruto));
43	        BigDecimal descontoCupom = cupom == null
44	                ? Dinheiro.ZERO
45	                : cupom.desconto(subtotal, itens, frete);
46	        BigDecimal seguro = Dinheiro.aCentavos(subtotal.multiply(regiao.percentual()));
47	        BigDecimal totalPedido = Dinheiro.aCentavos(
48	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
49	
50	        if (!forma.disponivelPara(totalPedido)) throw new ErroPedido("FORMA_PAGAMENTO_INDISPONIVEL");
51	
52	        ResultadoPagamento pag = forma.calcular(totalPedido, parcelas);
53	        BigDecimal ajuste = Dinheiro.aCentavos(pag.totalFinal().subtract(totalPedido));
54	
55	        return new CheckoutResponse(
56	                subtotal,
57	                descontoCupom,
58	                frete,
59	                modal.prazoDias(),
60	                seguro,
61	                ajuste,
62	                pag.totalFinal(),
63	                parcelas,
64	                pag.valorParcela(),
65	                nivel.cashback(subtotal),
66	                nivel.brinde(subtotal)
67	        );
68	    }
69	
70	    private List<Item> validaItens(List<CheckoutRequest.ItemRequest> itens) {
71	        if (itens == null || itens.isEmpty()) throw new ErroPedido("PEDIDO_INVALIDO");
72	        List<Item> resultado = new ArrayList<>(itens.size());
73	        for (CheckoutRequest.ItemRequest it : itens) {
74	            if (it == null
75	                    || it.precoUnitario() == null
76	                    || it.quantidade() == null
77	                    || it.pesoKg() == null
78	                    || it.precoUnitario().signum() <= 0
79	                    || it.quantidade() <= 0
80	                    || it.pesoKg().signum() <= 0) {
81	                throw new ErroPedido("PEDIDO_INVALIDO");
82	            }
83	            resultado.add(new Item(it.nome(), it.precoUnitario(), it.quantidade(), it.pesoKg()));
84	        }
85	        return resultado;
86	    }
87	
88	    private BigDecimal somaProdutos(List<Item> itens) {
89	        BigDecimal soma = BigDecimal.ZERO;
90	        for (Item it : itens) soma = soma.add(it.precoUnitario().multiply(BigDecimal.valueOf(it.quantidade())));
91	        return soma;
92	    }
93	
94	    private BigDecimal somaPeso(List<Item> itens) {
95	        BigDecimal soma = BigDecimal.ZERO;
96	        for (Item it : itens) soma = soma.add(it.pesoKg().multiply(BigDecimal.valueOf(it.quantidade())));
97	        return soma;
98	    }
99	
100	    private <E extends Enum<E>> E parse(Class<E> tipo, String valor, String codigoErro) {
101	        if (valor == null) throw new ErroPedido(codigoErro);
102	        try {
103	            return Enum.valueOf(tipo, valor);
104	        } catch (IllegalArgumentException e) {
105	            throw new ErroPedido(codigoErro);
106	        }
107	    }
108	}
