8	
9	public enum Cupom {
10	    BEMVINDO10 {
11	        @Override public BigDecimal desconto(BigDecimal subtotal, List<Item> itens, BigDecimal frete) {
12	            return Dinheiro.aCentavos(subtotal.multiply(new BigDecimal("0.10")));
13	        }
14	        @Override public boolean aplicavel(BigDecimal subtotal) { return true; }
15	    },
16	    MENOS50 {
17	        @Override public BigDecimal desconto(BigDecimal subtotal, List<Item> itens, BigDecimal frete) {
18	            return Dinheiro.aCentavos(new BigDecimal("50.00"));
19	        }
20	        @Override public boolean aplicavel(BigDecimal subtotal) {
21	            return subtotal.compareTo(new BigDecimal("300.00")) >= 0;
22	        }
23	    },
24	    FRETEGRATIS {
25	        @Override public BigDecimal desconto(BigDecimal subtotal, List<Item> itens, BigDecimal frete) {
26	            return Dinheiro.aCentavos(frete);
27	        }
28	        @Override public boolean aplicavel(BigDecimal subtotal) { return true; }
29	    },
30	    LEVE3PAGUE2 {
31	        @Override public BigDecimal desconto(BigDecimal subtotal, List<Item> itens, BigDecimal frete) {
32	            BigDecimal total = BigDecimal.ZERO;
33	            for (Item it : itens) {
34	                int gratis = it.quantidade() / 3;
35	                total = total.add(it.precoUnitario().multiply(BigDecimal.valueOf(gratis)));
36	            }
37	            return Dinheiro.aCentavos(total);
38	        }
39	        @Override public boolean aplicavel(BigDecimal subtotal) { return true; }
40	    };
41	
42	    public abstract BigDecimal desconto(BigDecimal subtotal, List<Item> itens, BigDecimal frete);
43	    public abstract boolean aplicavel(BigDecimal subtotal);
44	}
