1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	public enum FormaPagamento {
10	    PIX {
11	        @Override public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
12	            BigDecimal desconto = Dinheiro.aCentavos(total.multiply(new BigDecimal("0.05")));
13	            BigDecimal finalTotal = Dinheiro.aCentavos(total.subtract(desconto));
14	            return new ResultadoPagamento(finalTotal, finalTotal);
15	        }
16	        @Override public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
17	        @Override public boolean disponivelPara(BigDecimal total) { return true; }
18	    },
19	    CARTAO {
20	        private final BigDecimal taxa = new BigDecimal("0.0199");
21	
22	        @Override public ResultadoPagamento calcular(BigDecimal total, int parcelas) {
23	            if (parcelas <= 3) {
24	                BigDecimal parcela = Dinheiro.aCentavos(total.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN));
25	                BigDecimal finalTotal = Dinheiro.aCentavos(parcela.multiply(BigDecimal.valueOf(parcelas)));
26	                return new ResultadoPagamento(finalTotal, parcela);
27	            }
28	            MathContext mc = new MathContext(20, RoundingMode.HALF_EVEN);
29	            BigDecimal um = BigDecimal.ONE;
30	            BigDecimal umMaisT = um.add(taxa);
31	            BigDecimal pot = um;
32	            for (int i = 0; i < parcelas; i++) pot = pot.multiply(umMaisT, mc);
